class Warehouse:
    DEFAULT_STATUS = 'Shipped'

    def __init__(self):
        self._inventory = {}  # Product ID: Product
        self._orders = {}  # Order ID: Order

    @property
    def inventory(self):
        return self._inventory

    @property
    def orders(self):
        return self._orders

    def add_product(self, product_id, name, quantity):
        if self._has_product(product_id):
            self._update_product_quantity(product_id, quantity)
        else:
            self._create_product(product_id, name, quantity)

    def _has_product(self, product_id):
        return product_id in self._inventory

    def _create_product(self, product_id, name, quantity):
        self._inventory[product_id] = {'name': name, 'quantity': quantity}

    def _update_product_quantity(self, product_id, quantity):
        self._inventory[product_id]['quantity'] += quantity

    def update_product_quantity(self, product_id, quantity):
        if self._has_product(product_id):
            self._update_product_quantity(product_id, quantity)

    def get_product_quantity(self, product_id):
        if self._has_product(product_id):
            return self._inventory[product_id]['quantity']
        return None

    def create_order(self, order_id, product_id, quantity):
        if self._can_fulfill_order(product_id, quantity):
            self._decrement_inventory(product_id, quantity)
            self._create_order(order_id, product_id, quantity)
            return True
        return False

    def _can_fulfill_order(self, product_id, quantity):
        available_quantity = self.get_product_quantity(product_id)
        return available_quantity is not None and available_quantity >= quantity

    def _decrement_inventory(self, product_id, quantity):
        self._update_product_quantity(product_id, -quantity)

    def _create_order(self, order_id, product_id, quantity):
        self._orders[order_id] = {
            'product_id': product_id,
            'quantity': quantity,
            'status': self.DEFAULT_STATUS
        }

    def change_order_status(self, order_id, status):
        if self._has_order(order_id):
            self._orders[order_id]['status'] = status
            return True
        return False

    def _has_order(self, order_id):
        return order_id in self._orders

    def track_order(self, order_id):
        if self._has_order(order_id):
            return self._orders[order_id]['status']
        return None
